        // Delegating constructor syntax
        MyClass(int x, const Allocator& a = Allocator()) : MyClass(x, Compare(), a) {}  // Notes: Here, MyClass delegates to another constructor, passing default arguments for Compare(). In templates, the compiler must resolve template parameters at compile-time, ensuring that the delegated constructor matches the instantiation.

        // Target constructor
        template<typename CompareType>
        MyClass(int x, CompareType comp, const Allocator& a) { /* Implementation */ }
};

