#include <set>
#include <iostream>

template <class Key, class Compare = std::less<Key>, class Allocator = std::allocator<Key>>
class MySet {
public:
    // Delegating constructor example, similar to std::set
    MySet() : MySet(Compare(), Allocator()) {}  // Delegates to the full constructor

    template<class InputIterator>
    MySet(InputIterator first, InputIterator last, const Compare& comp = Compare(), const Allocator& a = Allocator())
        : MySet(first, last, comp, a) {}  // Further delegates

    MySet(std::initializer_list<Key> il, const Compare& comp = Compare(), const Allocator& a = Allocator())
        : MySet(il.begin(), il.end(), comp, a) {}  // Delegates to iterator-based constructor

private:
    // Full constructor implementation
    template<class InputIterator>
    MySet(InputIterator first, InputIterator last, const Compare& comp, const Allocator& a) {
        // Actual initialization logic, e.g., allocate nodes using 'a'
        std::cout << "Delegated constructor called" << std::endl;
    }
};

int main() {
    MySet<int> s;  // Invokes delegation chain
    return 0;
}
